            "CREATE TABLE briefing_scripts (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                briefing_id INTEGER NOT NULL REFERENCES briefings(id) ON DELETE CASCADE,\n                preset_id INTEGER,\n                preset_name TEXT NOT NULL,\n                roster_snapshot_json TEXT NOT NULL,\n                turns_json TEXT,\n                status TEXT NOT NULL DEFAULT 'generating',\n                error TEXT,\n                model_used TEXT,\n                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n            )",
            "CREATE TABLE briefings (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                watchlist_id INTEGER NOT NULL REFERENCES watchlists(id) ON DELETE CASCADE,\n                status TEXT NOT NULL DEFAULT 'generating',\n                error TEXT,\n                covers_through_item_id INTEGER,\n                covers_from_ts DATETIME,\n                selection_mode TEXT,\n                preset_id INTEGER,\n                model_used TEXT,\n                body_markdown TEXT,\n                item_count INTEGER DEFAULT 0,\n                featured_count INTEGER DEFAULT 0,\n                overflow_count INTEGER DEFAULT 0,\n                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP\n            )",
            "CREATE TABLE local_watchlist_alert_rules (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                job_id INTEGER,\n                name TEXT NOT NULL,\n                enabled INTEGER NOT NULL DEFAULT 1,\n                condition_type TEXT NOT NULL,\n                condition_value_json TEXT NOT NULL DEFAULT '{}',\n                severity TEXT NOT NULL DEFAULT 'warning',\n                created_at TEXT NOT NULL,\n                updated_at TEXT NOT NULL,\n                FOREIGN KEY (job_id) REFERENCES subscriptions(id) ON DELETE CASCADE\n            )",
            "CREATE TABLE local_watchlist_runs (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                source_id INTEGER NOT NULL,\n                job_id INTEGER,\n                batch_id TEXT,\n                status TEXT NOT NULL,\n                started_at TEXT,\n                finished_at TEXT,\n                stats_json TEXT,\n                error_msg TEXT,\n                log_text TEXT,\n                created_at TEXT NOT NULL,\n                updated_at TEXT NOT NULL,\n                FOREIGN KEY (source_id) REFERENCES subscriptions(id) ON DELETE CASCADE\n            )",
            "CREATE TABLE schema_version (\n                version INTEGER PRIMARY KEY NOT NULL\n            )",
            "CREATE TABLE site_configs (\n        id INTEGER PRIMARY KEY AUTOINCREMENT,\n        domain TEXT UNIQUE NOT NULL,\n        config_data TEXT NOT NULL,\n        created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n        updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n    )",
            "CREATE TABLE sqlite_sequence(name,seq)",
            "CREATE TABLE \"subscription_filters\" (\n                        id INTEGER PRIMARY KEY AUTOINCREMENT,\n                        subscription_id INTEGER,\n                        name TEXT NOT NULL,\n                        is_active BOOLEAN DEFAULT 1,\n                        conditions TEXT NOT NULL,\n                        action TEXT NOT NULL CHECK(action IN ('auto_ingest','auto_ignore','tag','priority','notify','include','exclude','flag')),\n                        action_params TEXT,\n                        priority INTEGER DEFAULT 0,\n                        is_include_required BOOLEAN DEFAULT 0,\n                        created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                        updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                        FOREIGN KEY (subscription_id) REFERENCES subscriptions(id) ON DELETE CASCADE\n                    )",
            "CREATE TABLE subscription_items (\n                id INTEGER PRIMARY KEY AUTOINCREMENT,\n                subscription_id INTEGER NOT NULL,\n                \n                -- Common fields\n                url TEXT NOT NULL,\n                title TEXT,\n                content_hash TEXT,\n                published_date DATETIME,\n                \n                -- Enhanced metadata\n                author TEXT,\n                categories TEXT,\n                enclosures TEXT,\n                extracted_data TEXT,\n                \n                -- Status tracking\n                status TEXT DEFAULT 'new' CHECK(status IN ('new', 'reviewed', 'ingested', 'ignored', 'error')),\n                media_id INTEGER,\n                processing_error TEXT,\n                \n                -- Change tracking for URLs\n                previous_hash TEXT,\n                change_percentage FLOAT,\n                diff_summary TEXT,\n                change_type TEXT CHECK(change_type IN (NULL, 'content', 'metadata', 'structural', 'new', 'removed')),\n                \n                -- Deduplication\n                canonical_url TEXT,\n                duplicate_of INTEGER,\n                \n                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,\n                updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, queued_for_briefing BOOLEAN DEFAULT 0, run_id INTEGER, alert_matches TEXT, content TEXT, content_format TEXT, content_kind TEXT, is_flagged BOOLEAN DEFAULT 0, effective_date TEXT GENERATED ALWAYS AS (COALESCE(datetime(published_date), datetime(created_at))) VIRTUAL,\n                \n                FOREIGN KEY (subscription_id) REFERENCES subscriptions(id) ON DELETE CASCADE,\n                FOREIGN KEY (duplicate_of) REFERENCES subscription_items(id),\n                UNIQUE(subscription_id, url, content_hash)\n            )",
