            "CREATE TRIGGER update_watchlists_timestamp\n            AFTER UPDATE ON watchlists\n            BEGIN\n                UPDATE watchlists SET updated_at = CURRENT_TIMESTAMP WHERE id = NEW.id;\n            END",
